-- Rodos Royal шпон: точні кольори, види полотна й фото з офіційних карток Rodos.
-- Скрипт не змінює інші колекції або бренди. Кожна модель очищається тільки перед повторним наповненням її конфігуратора.
do $$ begin if (select count(*) from public.products where slug in ('rodos-official-1mt8i9p')) <> 1 then raise exception 'Не знайдено всі моделі Rodos Royal шпон для пакета — каталог не змінено'; end if; end $$;
begin;
delete from public.product_options where product_slug = 'rodos-official-1mt8i9p';
delete from public.product_variants where product_slug = 'rodos-official-1mt8i9p';
delete from public.product_media where product_slug = 'rodos-official-1mt8i9p' and label like 'config:%';
commit;
select product_slug, count(*) filter (where option_group = 'color') as кольорів, count(*) filter (where option_group = 'configuration') as видів_полотна from public.product_options where product_slug in ('rodos-official-1mt8i9p') group by product_slug order by product_slug;